def combination_sum3(k, n):
    result = []
    def backtrack(start, path, remaining):
        if len(path) == k and remaining == 0:
            result.append(list(path))
            return
        if len(path) == k or remaining <= 0:
            return
        for num in range(start, 10):
            if num > remaining:
                break
            path.append(num)
            backtrack(num + 1, path, remaining - num)
            path.pop()
    backtrack(1, [], n)
    return result

