def solve_sudoku(board):
    def find_empty():
        for i in range(9):
            for j in range(9):
                if board[i][j] == '.':
                    return i, j
        return None
    def valid(r, c, num):
        for i in range(9):
            if board[r][i] == num or board[i][c] == num:
                return False
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if board[i][j] == num:
                    return False
        return True
    empty = find_empty()
    if not empty:
        return True
    r, c = empty
    for num in '123456789':
        if valid(r, c, num):
            board[r][c] = num
            if solve_sudoku(board):
                return True
            board[r][c] = '.'
    return False

