def three_sum_backtrack(nums):
    nums.sort()
    result = []
    n = len(nums)
    def backtrack(start, path, remaining):
        if len(path) == 3 and remaining == 0:
            result.append(list(path))
            return
        if len(path) >= 3:
            return
        for i in range(start, n):
            if i > start and nums[i] == nums[i-1]:
                continue
            if nums[i] > remaining and len(path) > 0:
                break
            path.append(nums[i])
            backtrack(i + 1, path, remaining - nums[i])
            path.pop()
    backtrack(0, [], 0)
    return result

