def generate_parenthesis_iter(n):
    result = []
    stack = [('', 0, 0)]
    while stack:
        path, open_count, close_count = stack.pop()
        if len(path) == 2 * n:
            result.append(path)
            continue
        if open_count < n:
            stack.append((path + '(', open_count + 1, close_count))
        if close_count < open_count:
            stack.append((path + ')', open_count, close_count + 1))
    return result

# Example: generate_parenthesis_iter(2) -> ['(())', '()()']
# Time: Catalan O(4^n / n^(3/2)), Space: O(n). Explicit stack mirrors the recursive structure.

