def unique_paths(m, n):
    memo = {}
    def dfs(r, c):
        if r == m - 1 and c == n - 1:
            return 1
        if r >= m or c >= n:
            return 0
        if (r, c) in memo:
            return memo[(r, c)]
        memo[(r, c)] = dfs(r + 1, c) + dfs(r, c + 1)
        return memo[(r, c)]
    return dfs(0, 0)

# Example: unique_paths(3, 3) -> 6
