def partition_palindrome(s):
    result = []
    n = len(s)
    def is_pal(sub):
        return sub == sub[::-1]
    def backtrack(start, path):
        if start == n:
            result.append(list(path))
            return
        for end in range(start + 1, n + 1):
            sub = s[start:end]
            if is_pal(sub):
                path.append(sub)
                backtrack(end, path)
                path.pop()
    backtrack(0, [])
    return result

# Example: partition_palindrome('aab') -> [['a','a','b'],['aa','b']]
# Time: O(n * 2^n), Space: O(n). Try every palindrome prefix and recurse on the rest.

def word_break_sentences(s, word_dict):
    words = set(word_dict)
    memo = {}
    def dfs(index):
        if index in memo:
            return memo[index]
        if index == len(s):
            return ['']
        results = []
        for end in range(index + 1, len(s) + 1):
            word = s[index:end]
            if word in words:
                tails = dfs(end)
                for tail in tails:
                    results.append(word + (' ' + tail if tail else ''))
        memo[index] = results
        return results
    return dfs(0)

# Example: word_break_sentences('catsanddog', ['cat','cats','and','sand','dog']) -> ['cat sand dog', 'cats and dog']
# Time: O(n * 2^n) worst, Space: O(n * 2^n). Memoized DFS collecting sentence tails.
